      // Wait for navigation to complete and new block content to render
      await expectElement(page.getByText(/block 2 of 2/i)).toBeVisible()
      await expectElement(page.getByRole('table')).toBeVisible()

      // Debug: check what exercise names are visible in the header
      const header = page.getByRole('heading', { level: 1 })
      await expectElement(header).toBeVisible()
      await expectElement(page.getByText('Deadlift')).toBeVisible()

      // Navigate back to first block
      await page.getByRole('button', { name: /previous block/i }).click()

      await expectElement(page.getByText(/block 1 of 2/i)).toBeVisible()
      // Wait for the table to re-render with the new block's content
      await expectElement(page.getByRole('table')).toBeVisible()
      await expectElement(page.getByText('Bench Press')).toBeVisible()

      cleanup()
    })
  })

